def h(z):
    # h(z) = 9 * (2*z**2 + 1) / (2*z + 1)
    if z <= 0:
        return float('inf') # z must be positive real number
    return 9 * (2*z**2 + 1) / (2*z + 1)

# Test specific values of z
z_values = [0.5, 1, 2, 3]
results = {}
for z in z_values:
    results[z] = h(z)

print("Ratio U = 9(2z^2+1) / (2z+1) for various z:")
for z, u in results.items():
    print(f"z = {z}, U = {u}")
